changeSet.sql:


DELETE UPDATE_APP_LOG FROM UPDATE_APP_LOG
              JOIN APP ON APP.id = UPDATE_APP_LOG.appId
              JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
              JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE APP_ERROR FROM APP_ERROR
              JOIN APP ON APP.id = APP_ERROR.appId
              JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
              JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE SERVICE FROM SERVICE
                  JOIN APP ON APP.id = SERVICE.appId
                  JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
                  JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE LABEL FROM LABEL
                  JOIN APP ON LABEL.resourceType='app' and LABEL.resourceId = APP.id
                  JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
                  JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE APP_CONTROLLED_RESOURCE FROM APP_CONTROLLED_RESOURCE
                  JOIN APP ON APP.id = APP_CONTROLLED_RESOURCE.appId
                  JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
                  JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE APP FROM APP
                  JOIN NODEPOOL ON APP.nodepoolId = NODEPOOL.id
                  JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE NODEPOOL FROM NODEPOOL
                  JOIN KUBERNETES_CLUSTER ON NODEPOOL.clusterId = KUBERNETES_CLUSTER.id
WHERE KUBERNETES_CLUSTER.cloudProvider = 'AZURE';

DELETE FROM KUBERNETES_CLUSTER where cloudProvider = 'AZURE';



DELETE RUNTIME_CONTROLLED_RESOURCE FROM RUNTIME_CONTROLLED_RESOURCE
                  JOIN CLUSTER ON CLUSTER.id = RUNTIME_CONTROLLED_RESOURCE.runtimeId
WHERE CLUSTER.cloudProvider = 'AZURE';

DELETE LABEL FROM LABEL
                  JOIN CLUSTER ON LABEL.resourceType='runtime' and LABEL.resourceId = CLUSTER.id
WHERE CLUSTER.cloudProvider = 'AZURE';

DELETE CLUSTER_IMAGE FROM CLUSTER_IMAGE
                  JOIN CLUSTER ON CLUSTER_IMAGE.clusterId = CLUSTER.id
WHERE CLUSTER.cloudProvider = 'AZURE';

DELETE CLUSTER_ERROR FROM CLUSTER_ERROR
                  JOIN CLUSTER ON CLUSTER_ERROR.clusterId = CLUSTER.id
WHERE CLUSTER.cloudProvider = 'AZURE';

DELETE FROM CLUSTER WHERE cloudProvider = 'AZURE';

DELETE FROM RUNTIME_CONFIG WHERE cloudService = 'AZURE_VM';



DELETE LABEL FROM LABEL
                  JOIN PERSISTENT_DISK ON LABEL.resourceType='persistentDisk' and LABEL.resourceId = PERSISTENT_DISK.id
WHERE PERSISTENT_DISK.cloudProvider = 'AZURE';

DELETE FROM PERSISTENT_DISK WHERE cloudProvider = 'AZURE';
